    // 5. Vaccination drive
    [
        'slug' => 'uttar-pradesh-begins-school-based-measles-rubella-catch-up-vaccination-drive',
        'category' => 'health',
        'page' => 'health-watch',
        'city' => null,
        'source' => 'PTI',
        'is_breaking' => false,
        'importance' => 7,
        'read_minutes' => 3,
        'minutes_ago' => 75,
        'photo' => 'health-1.jpg',
        'en' => [
            'headline' => 'Uttar Pradesh begins school-based measles-rubella catch-up vaccination drive for children',
            'card_text' => 'Uttar Pradesh on Thursday began a month-long measles-rubella catch-up vaccination drive aimed at children aged nine months to 15 years who missed earlier doses. Health workers will hold sessions in schools, anganwadi centres and health sub-centres. Officials said the vaccine is free, and parents will receive SMS reminders about session dates in their area.',
            'key_points' => [
                'The drive aims to reach about 1.1 crore children across all 75 districts by early December.',
                'Children who already received two doses on schedule do not need another dose, officials said.',
                'Mobile teams will visit brick kilns, construction sites and migrant settlements to reach children outside schools.',
            ],
            'why_it_matters' => 'Measles spreads very easily, and closing gaps in vaccination protects both individual children and the wider community.',
            'simple_text' => 'Measles and rubella are illnesses caused by viruses that spread quickly among children. A vaccine can protect against both. Some children missed their doses in earlier years, so Uttar Pradesh is running a special drive for a month. Health workers will come to schools and anganwadis to give the vaccine for free. Parents will get a message telling them when to bring their child. Doctors say vaccinating many children together helps keep the whole community safe.',
            'full_text' => "The Uttar Pradesh health department on Thursday launched a month-long catch-up vaccination drive against measles and rubella, targeting children between nine months and 15 years of age who may have missed one or both routine doses.\n\nOfficials said about 1.1 crore children are expected to be covered across 75 districts by early December. Vaccination sessions will be held in government and private schools, anganwadi centres and health sub-centres on fixed days. Mobile teams will also visit brick kilns, construction sites and settlements of migrant workers, where children are more likely to have missed routine immunisation.\n\nThe vaccine is being provided free of cost. A senior state immunisation officer said children who have already received two doses on time, as recorded on their vaccination card, do not need an additional dose. Parents have been advised to carry the card to the session, and to inform health workers if the child is unwell on the day.\n\nDoctors said mild fever or soreness at the injection site can occur and usually settles within a day or two. Every session will have a trained staff member to observe children for 30 minutes after vaccination. Parents can call the state health helpline 104 for session details.",
        ],
        'hi' => [
            'headline' => 'उत्तर प्रदेश में बच्चों के लिए खसरा-रूबेला टीकाकरण का विशेष अभियान शुरू',
            'card_text' => 'उत्तर प्रदेश में गुरुवार से खसरा-रूबेला का एक महीने का विशेष टीकाकरण अभियान शुरू हुआ। यह नौ महीने से 15 साल तक के उन बच्चों के लिए है जिनकी पहले की खुराक छूट गई थी। स्वास्थ्यकर्मी स्कूलों, आंगनबाड़ी केंद्रों और उपकेंद्रों में टीका लगाएंगे। टीका मुफ्त है और माता-पिता को सत्र की तारीख एसएमएस से बताई जाएगी।',
            'key_points' => [
                'दिसंबर की शुरुआत तक सभी 75 जिलों में करीब 1.1 करोड़ बच्चों तक पहुंचने का लक्ष्य है।',
                'अधिकारियों के मुताबिक जिन बच्चों को समय पर दोनों खुराक मिल चुकी हैं, उन्हें दोबारा टीके की जरूरत नहीं है।',
                'स्कूल से बाहर के बच्चों तक पहुंचने के लिए मोबाइल टीमें ईंट भट्ठों और निर्माण स्थलों पर जाएंगी।',
            ],
            'why_it_matters' => 'खसरा बहुत तेजी से फैलता है, इसलिए टीकाकरण की कमियां दूर करना बच्चों और पूरे समुदाय दोनों की सुरक्षा के लिए जरूरी है।',
            'simple_text' => 'खसरा और रूबेला वायरस से होने वाली बीमारियां हैं जो बच्चों में जल्दी फैलती हैं। एक टीका दोनों से बचाव करता है। कुछ बच्चों को पिछले सालों में यह टीका नहीं लग पाया, इसलिए उत्तर प्रदेश एक महीने का खास अभियान चला रहा है। स्वास्थ्यकर्मी स्कूलों और आंगनबाड़ी में आकर मुफ्त टीका लगाएंगे। माता-पिता को संदेश मिलेगा कि बच्चे को कब लाना है। डॉक्टर कहते हैं कि ज्यादा बच्चों को टीका लगने से पूरा इलाका सुरक्षित रहता है।',
            'full_text' => "उत्तर प्रदेश स्वास्थ्य विभाग ने गुरुवार को खसरा और रूबेला के खिलाफ एक महीने का विशेष टीकाकरण अभियान शुरू किया। इसका लक्ष्य नौ महीने से 15 साल तक के वे बच्चे हैं जिनकी नियमित टीकाकरण की एक या दोनों खुराक छूट गई हो।\n\nअधिकारियों के अनुसार दिसंबर की शुरुआत तक 75 जिलों में करीब 1.1 करोड़ बच्चों को कवर करने की योजना है। सरकारी और निजी स्कूलों, आंगनबाड़ी केंद्रों और स्वास्थ्य उपकेंद्रों में तय दिनों पर टीकाकरण सत्र होंगे। मोबाइल टीमें ईंट भट्ठों, निर्माण स्थलों और प्रवासी मजदूरों की बस्तियों में भी जाएंगी, जहां बच्चों का टीकाकरण छूटने की आशंका ज्यादा रहती है।\n\nटीका पूरी तरह मुफ्त है। राज्य के एक वरिष्ठ टीकाकरण अधिकारी ने बताया कि जिन बच्चों के टीकाकरण कार्ड में दोनों खुराक समय पर दर्ज हैं, उन्हें अतिरिक्त खुराक की जरूरत नहीं है। माता-पिता से कहा गया है कि सत्र में टीकाकरण कार्ड साथ लाएं और अगर बच्चा उस दिन बीमार हो तो स्वास्थ्यकर्मी को जरूर बताएं।\n\nडॉक्टरों के मुताबिक टीके के बाद हल्का बुखार या इंजेक्शन की जगह पर दर्द हो सकता है, जो आमतौर पर एक-दो दिन में ठीक हो जाता है। हर सत्र में प्रशिक्षित कर्मचारी टीके के बाद 30 मिनट तक बच्चों पर नजर रखेंगे। सत्र की जानकारी के लिए राज्य हेल्पलाइन 104 पर संपर्क किया जा सकता है।",
        ],
    ],

